/* The build injects all hashed route/data chunks; artwork is cached on demand. */
const PRECACHE = /* __GYMMIIE_PRECACHE__ */ null;
const CACHE = `gymmiie-${PRECACHE?.version ?? 'unbuilt'}`;

async function installShell() {
  if (!PRECACHE)
    throw new Error(
      'The service worker must be generated by the production build.',
    );
  const cache = await caches.open(CACHE);
  try {
    await cache.addAll(PRECACHE.urls);
  } catch (error) {
    await caches.delete(CACHE);
    throw error;
  }
}

self.addEventListener('install', (event) => {
  // Normal activation waits for existing workouts to close before replacing their worker.
  event.waitUntil(installShell());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key.startsWith('gymmiie-') && key !== CACHE)
          .map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    })(),
  );
});

async function navigate(request) {
  const cache = await caches.open(CACHE);
  // Keep HTML and lazy chunks on the active build while an update waits for open workouts.
  const shell = await cache.match('/');
  if (shell) return shell;
  try {
    const response = await fetch(request);
    if (response.ok) {
      if (response.headers.get('content-type')?.includes('text/html')) {
        try {
          await cache.put('/', response.clone());
        } catch {
          /* Cache quota must not block navigation. */
        }
      }
      return response;
    }
    return response;
  } catch {
    return Response.error();
  }
}

async function staticAsset(request) {
  const cache = await caches.open(CACHE);
  // Build assets are identical regardless of the browser's Origin request header.
  // Some hosts add Vary: Origin, unlike the worker's precache requests.
  const isPrecached = PRECACHE.urls.includes(new URL(request.url).pathname);
  const cached = await cache.match(request, { ignoreVary: isPrecached });
  if (cached) return cached;
  const isArtwork = new URL(request.url).pathname.startsWith('/art/');
  const response = await fetch(
    request,
    isArtwork ? { cache: 'reload' } : undefined,
  );
  if (response.ok && response.type === 'basic') {
    try {
      await cache.put(request, response.clone());
    } catch {
      /* Artwork caching is best effort. */
    }
  }
  return response;
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (
    url.origin !== self.location.origin ||
    url.pathname === '/api' ||
    url.pathname.startsWith('/api/')
  )
    return;
  event.respondWith(
    request.mode === 'navigate' ? navigate(request) : staticAsset(request),
  );
});
